-- Create "lottery_accounts" table
CREATE TABLE "lottery_accounts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "activity_id" bigint NOT NULL, "user_id" bigint NOT NULL, "period" character varying NOT NULL, "balance" integer NOT NULL DEFAULT 0, "auto_granted" boolean NOT NULL DEFAULT false, "version" integer NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "lotteryaccount_subsite_id_activity_id_user_id_period" to table: "lottery_accounts"
CREATE UNIQUE INDEX "lotteryaccount_subsite_id_activity_id_user_id_period" ON "lottery_accounts" ("subsite_id", "activity_id", "user_id", "period");
-- Create "lottery_activities" table
CREATE TABLE "lottery_activities" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "name" character varying NOT NULL, "description" text NOT NULL DEFAULT '', "image" character varying NOT NULL DEFAULT '', "status" character varying NOT NULL DEFAULT 'draft', "start_at" timestamptz NOT NULL, "end_at" timestamptz NOT NULL, "timezone" character varying NOT NULL DEFAULT 'Asia/Shanghai', "chance_mode" character varying NOT NULL DEFAULT 'once', "chance_count" integer NOT NULL DEFAULT 3, "revision" integer NOT NULL DEFAULT 1, "published" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- Create index "lotteryactivity_subsite_id_status" to table: "lottery_activities"
CREATE INDEX "lotteryactivity_subsite_id_status" ON "lottery_activities" ("subsite_id", "status");
-- Create "lottery_chance_logs" table
CREATE TABLE "lottery_chance_logs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "activity_id" bigint NOT NULL, "user_id" bigint NOT NULL, "period" character varying NOT NULL, "amount" integer NOT NULL, "kind" character varying NOT NULL, "request_key" character varying NOT NULL, "remark" character varying NOT NULL DEFAULT '', "admin_id" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "lotterychancelog_subsite_id_activity_id_user_id_request_key" to table: "lottery_chance_logs"
CREATE UNIQUE INDEX "lotterychancelog_subsite_id_activity_id_user_id_request_key" ON "lottery_chance_logs" ("subsite_id", "activity_id", "user_id", "request_key");
-- Create "lottery_draws" table
CREATE TABLE "lottery_draws" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "activity_id" bigint NOT NULL, "user_id" bigint NOT NULL, "draw_no" character varying NOT NULL, "request_key" character varying NOT NULL, "activity_name" character varying NOT NULL, "prize_name" character varying NOT NULL DEFAULT '', "mode" character varying NOT NULL DEFAULT '', "status" character varying NOT NULL, "prize_id" bigint NOT NULL DEFAULT 0, "product_id" bigint NOT NULL DEFAULT 0, "sku_id" bigint NOT NULL DEFAULT 0, "card_id" bigint NULL, "cost" bigint NOT NULL DEFAULT 0, "revision" integer NOT NULL, "rule_snapshot" jsonb NULL, "content" bytea NULL, "delivered_at" timestamptz NULL, "admin_id" bigint NOT NULL DEFAULT 0, "remark" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "lottery_draws_draw_no_key" to table: "lottery_draws"
CREATE UNIQUE INDEX "lottery_draws_draw_no_key" ON "lottery_draws" ("draw_no");
-- Create index "lotterydraw_card_id" to table: "lottery_draws"
CREATE UNIQUE INDEX "lotterydraw_card_id" ON "lottery_draws" ("card_id");
-- Create index "lotterydraw_product_id_sku_id" to table: "lottery_draws"
CREATE INDEX "lotterydraw_product_id_sku_id" ON "lottery_draws" ("product_id", "sku_id");
-- Create index "lotterydraw_subsite_id_activity_id_status" to table: "lottery_draws"
CREATE INDEX "lotterydraw_subsite_id_activity_id_status" ON "lottery_draws" ("subsite_id", "activity_id", "status");
-- Create index "lotterydraw_subsite_id_activity_id_user_id_request_key" to table: "lottery_draws"
CREATE UNIQUE INDEX "lotterydraw_subsite_id_activity_id_user_id_request_key" ON "lottery_draws" ("subsite_id", "activity_id", "user_id", "request_key");
-- Create index "lotterydraw_subsite_id_user_id_id" to table: "lottery_draws"
CREATE INDEX "lotterydraw_subsite_id_user_id_id" ON "lottery_draws" ("subsite_id", "user_id", "id");
-- Create "lottery_prizes" table
CREATE TABLE "lottery_prizes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "activity_id" bigint NOT NULL, "name" character varying NOT NULL, "image" character varying NOT NULL DEFAULT '', "mode" character varying NOT NULL, "product_id" bigint NOT NULL DEFAULT 0, "sku_id" bigint NOT NULL DEFAULT 0, "probability" integer NOT NULL DEFAULT 0, "quantity" integer NOT NULL DEFAULT 1, "issued" integer NOT NULL DEFAULT 0, "sort" integer NOT NULL DEFAULT 0, "enabled" boolean NOT NULL DEFAULT true, "content" bytea NULL, PRIMARY KEY ("id"));
-- Create index "lotteryprize_product_id_sku_id" to table: "lottery_prizes"
CREATE INDEX "lotteryprize_product_id_sku_id" ON "lottery_prizes" ("product_id", "sku_id");
-- Create index "lotteryprize_subsite_id_activity_id_enabled" to table: "lottery_prizes"
CREATE INDEX "lotteryprize_subsite_id_activity_id_enabled" ON "lottery_prizes" ("subsite_id", "activity_id", "enabled");
-- Create "lottery_revisions" table
CREATE TABLE "lottery_revisions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "activity_id" bigint NOT NULL, "revision" integer NOT NULL, "admin_id" bigint NOT NULL, "snapshot" jsonb NOT NULL, PRIMARY KEY ("id"));
-- Create index "lotteryrevision_subsite_id_activity_id_revision" to table: "lottery_revisions"
CREATE UNIQUE INDEX "lotteryrevision_subsite_id_activity_id_revision" ON "lottery_revisions" ("subsite_id", "activity_id", "revision");
